import React, { useMemo } from "react";
import { useNavigate } from "react-router-dom";
import "./style/Results.css";

function Results() {
  const navigate = useNavigate();

  // اجلب آخر نتائج محفوظة
  const saved = useMemo(() => {
    try {
      return JSON.parse(localStorage.getItem("fs_results")) || null;
    } catch {
      return null;
    }
  }, []);

  const data = saved?.data || {};

  // محاولة لقراءة بعض الحقول الشائعة
  const gaAcc = data.genetic_accuracy ?? data.ga_accuracy ?? data.accuracy ?? null;
  const miAcc = data.mutual_info_accuracy ?? data.mi_accuracy ?? null;
  const pcaAcc = data.pca_accuracy ?? null;
  const rfeAcc = data.rfe_accuracy ?? null;
  const chiAcc = data.chi_accuracy ?? null;

  const selectedCount =
    data.num_selected_features ?? data.selected_features_count ?? data.num_selected ?? null;

  return (
    <div className="results-container">
      <h1 className="results-title">نتائج التحليل</h1>

      {!saved ? (
        <p className="results-description">
          لا توجد نتائج محفوظة. الرجاء العودة ورفع ملف.
        </p>
      ) : (
        <>
          <p className="results-description">
            آخر تشغيل: <strong>{new Date(saved.receivedAt).toLocaleString()}</strong> — Endpoint:
            <strong style={{ direction: "ltr", marginInlineStart: 6 }}>{saved.endpoint}</strong>
          </p>

          <div className="results-box">
            {selectedCount != null && (
              <p>
                عدد الخصائص المختارة: <strong>{selectedCount}</strong>
              </p>
            )}
            {gaAcc != null && (
              <p>
                دقة GA: <strong>{(gaAcc * (gaAcc <= 1 ? 100 : 1)).toFixed(2)}%</strong>
              </p>
            )}
            {miAcc != null && (
              <p>
                دقة MI: <strong>{(miAcc * (miAcc <= 1 ? 100 : 1)).toFixed(2)}%</strong>
              </p>
            )}
            {pcaAcc != null && (
              <p>
                دقة PCA: <strong>{(pcaAcc * (pcaAcc <= 1 ? 100 : 1)).toFixed(2)}%</strong>
              </p>
            )}
            {rfeAcc != null && (
              <p>
                دقة RFE: <strong>{(rfeAcc * (rfeAcc <= 1 ? 100 : 1)).toFixed(2)}%</strong>
              </p>
            )}
            {chiAcc != null && (
              <p>
                دقة Chi-Square: <strong>{(chiAcc * (chiAcc <= 1 ? 100 : 1)).toFixed(2)}%</strong>
              </p>
            )}
          </div>

          {/* زر يودّيك للمقارنة */}
          <button onClick={() => navigate("/comparison")} className="results-btn">
            الانتقال إلى المقارنة
          </button>

          {/* رجوع للرفع */}
          <button onClick={() => navigate("/upload")} className="results-btn" style={{ marginInlineStart: 8 }}>
            رفع ملف آخر
          </button>
        </>
      )}
    </div>
  );
}

export default Results;
